from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    separators = [
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    ]
    sep = next((c for c in separators if grid[0][c] == 0), separators[0])
    n = min(sep, w - sep - 1)
    left = [row[:n] for row in grid]
    right = [row[sep + 1:sep + 1 + n] for row in grid]

    def bg(panel):
        return Counter(x for row in panel for x in row).most_common(1)[0][0]

    bl, br = bg(left), bg(right)
    return [
        [2 if left[r][c] != bl or right[r][c] != br else 3 for c in range(n)]
        for r in range(h)
    ]
